INSERT INTO aranceles_partida (id, capitulo_id, codigo, descripcion) VALUES
(1, 1, '01.01', 'Caballos, asnos, mulos y burdéganos, vivos.'),
(2, 1, '01.02', 'Animales vivos de la especie bovina.'),
(3, 1, '01.03', 'Animales vivos de la especie porcina.'),
(4, 1, '01.04', 'Animales vivos de las especies ovina o caprina.'),
(5, 1, '01.05', 'Gallos, gallinas, patos, gansos, pavos (gallipavos) y pintadas, de las especies domésticas, vivos.'),
(6, 1, '01.06', 'Los demás animales vivos.'),
(7, 2, '02.01', 'Carne de animales de la especie bovina, fresca o refrigerada.'),
(8, 2, '02.02', 'Carne de animales de la especie bovina, congelada.'),
(9, 2, '02.03', 'Carne de animales de la especie porcina, fresca, refrigerada o congelada.'),
(10, 2, '02.04', 'Carne de animales de las especies ovina o caprina, fresca, refrigerada o congelada.'),
(11, 2, '02.05', 'Carne de animales de las especies caballar, asnal o mular, fresca, refrigerada o congelada.'),
(12, 2, '02.06', 'Despojos comestibles de animales de las especies bovina, porcina, ovina, caprina, caballar, asnal o mular, frescos, refrigerados o congelados.'),
(13, 2, '02.07', 'Carne y despojos comestibles, de aves de la partida 01.05, frescos, refrigerados o congelados.'),
(14, 2, '02.08', 'Las demás carnes y despojos comestibles, frescos, refrigerados o congelados.'),
(15, 2, '02.09', 'Tocino sin partes magras y grasa de cerdo o de ave sin fundir ni extraer de otro modo, frescos, refrigerados, congelados, salados o en salmuera, secos o ahumados.'),
(16, 2, '02.10', 'Carne y despojos comestibles, salados o en salmuera, secos o ahumados; harina y polvo comestibles, de carne o de despojos.'),
(17, 3, '03.01', 'Peces vivos.'),
(18, 3, '03.02', 'Pescado fresco o refrigerado, excepto los filetes y demás carne de pescado de la partida 03.04.'),
(19, 3, '03.03', 'Pescado congelado, excepto los filetes y demás carne de pescado de la partida 03.04.'),
(20, 3, '03.04', 'Filetes y demás carne de pescado (incluso picada), frescos, refrigerados o congelados.'),
(21, 3, '03.05', 'Pescado seco, salado o en salmuera; pescado ahumado, incluso cocido antes o durante el ahumado.'),
(22, 3, '03.06', 'Crustáceos, incluso pelados, vivos, frescos, refrigerados, congelados, secos, salados o en salmuera...'),
(23, 3, '03.07', 'Moluscos, incluso separados de sus valvas, vivos, frescos, refrigerados, congelados, secos, salados o en salmuera...'),
(24, 3, '03.08', 'Invertebrados acuáticos, excepto los crustáceos y moluscos, vivos, frescos, refrigerados, congelados...'),
(25, 3, '03.09', 'Harina, polvo y «pellets» de pescado, crustáceos, moluscos y demás invertebrados acuáticos, aptos para la alimentación humana.');
